import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Textarea from "../../ui/shadcn-textarea";

// MODEL

export const Model = S.Struct({
  value: S.String,
});

export type Model = typeof Model.Type;

// MESSAGE

export const UpdatedBio = m("UpdatedBio", { value: S.String });

export const Message = S.Union([UpdatedBio]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ value: "" }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      UpdatedBio: ({ value }) => [evo(model, { value: () => value }), []],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("max-w-sm space-y-3")],
    [
      Textarea.view<Message>({
        id: "bio-textarea",
        value: model.value,
        rows: 4,
        placeholder: "Tell us about yourself...",
        onInput: (value) => UpdatedBio({ value }),
        toView: (attributes) =>
          h.div(
            [h.Class(Textarea.shadcnTextareaFieldClassName)],
            [
              h.label(
                [
                  ...attributes.label,
                  h.Class(Textarea.shadcnTextareaLabelClassName),
                ],
                ["Bio"]
              ),
              h.textarea(
                [
                  ...attributes.textarea,
                  h.Class(Textarea.shadcnTextareaClassName),
                ],
                []
              ),
              h.p(
                [
                  ...attributes.description,
                  h.Class(Textarea.shadcnTextareaDescriptionClassName),
                ],
                ["A brief introduction about yourself."]
              ),
            ]
          ),
      }),
      h.p(
        [h.Class("text-sm text-gray-700")],
        [`Characters: ${model.value.length.toString()}`]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as ShadcnTextareaBasicExample from "./main";

describe("Shadcn Textarea Basic example", () => {
  test("updates typed feedback", () => {
    Scene.scene(
      {
        update: ShadcnTextareaBasicExample.update,
        view: ShadcnTextareaBasicExample.view,
      },
      Scene.with(ShadcnTextareaBasicExample.init()[0]),
      Scene.expect(Scene.role("textbox", { name: "Bio" })).toExist(),
      Scene.expect(Scene.text("Characters: 0")).toExist(),
      Scene.type(Scene.role("textbox", { name: "Bio" }), "Ada"),
      Scene.expect(Scene.text("Characters: 3")).toExist()
    );
  });
});
